report=dict(candidate='0.9.58 continuation',acceptedApp='0.9.51',status='UNRELEASED',passed=all(checks.values()),checks=checks,checkedMmaLabels=len(mma['checkedLabels']),mmaNeuralContactPairs=len(neural),mmaNeuralContacts=neural,mmaDuralContactPairs=len(mma['contacts'])-len(neural),newPerLabelArterialFolds=sum(r['newIntersections']for r in artery['results']),newPerLabelBrainFolds=sum(r['newIntersections']for r in brain['results']),checkedArterialLabels=len(artery['results']),checkedBrainLabels=len(brain['results']),nativeInterfaceMismatchMm=native['maxMismatchMm'],missingNativeCoordinatePairs=native['missingNativeCoordinatePairs'],receiverNeuralContactPairs=sum(c['domain']=='neural'for c in rc),receiverArterialContactPairs=sum(c['domain']=='arterial'for c in rc),receiverBoneContactPairs=sum(c['domain']=='bone'for c in rc),receiverContacts=rc,installedCollateralRepairs=installed,distortionScreenFlaggedLabels=[r['node']for r in distortion['results']if r.get('edgeRatioOutsideHalfToDouble',0)],candidateBufferSha256={p.name:sha(p)for p in sorted(out.glob('*.bin'))},acceptedAssetSha256=public,limitations=['Surface intersection tests do not establish lumen patency or anatomical validity.','Dural-reflection contacts are reported separately from neural tissue.','Receiver bone contacts and residual collateral neural contacts remain release blockers.','The public app retains recovered v0.9.51 model assets.','The updated reviewer compares separate vertex/index buffers for source and candidate, including changed cortex and remeshed collectors.'])
